/**
 * The page header: a skip link to the main content, the brand, the two navigation links (the current one carries
 * aria-current) and the theme button. `current` is the route area. Axes: layout (inline, stacked), position
 * (static, sticky), actions (none, cta).
 */
import { type ReactNode } from "react";
import { Block, Button, Container, Group, LinkPlain } from "../compose";
import { MenuEntry } from "../components/menu-entry";
import { NavBlock } from "../components/nav-block";
import { cn, tpl, uniqLabel, urlOf } from "../utils";
import type { SiteHeaderLabels, SiteRoutes } from "./site-header.types";

export type SiteHeaderProps = {
  labels: SiteHeaderLabels;
  routes?: SiteRoutes;
  current: string;
  layout?: "inline" | "stacked";
  position?: "static" | "sticky";
  actions?: "none" | "cta";
  cta?: string;
  ctaHref?: string;
  landmarkLabel?: string;
  onTheme?: () => void;
};

export function SiteHeader({
  labels,
  routes,
  current,
  layout = "inline",
  position = "static",
  actions = "none",
  cta,
  ctaHref,
  landmarkLabel,
  onTheme,
}: SiteHeaderProps) {
  return (
    <Block
      tag="header"
      className={cn(
        "border-b border-border bg-background",
        (((position as string) === "sticky") ? "sticky top-0 z-40" : "")
      )}
      data-testid="site-header"
      data-layout={layout}
      aria-label={landmarkLabel}
    >
      <LinkPlain
        href="#main-content"
        className={"sr-only focus:not-sr-only focus:fixed focus:left-2 focus:top-2 focus:z-50 focus:rounded focus:bg-background " +
          "focus:px-4 focus:py-2 focus:text-sm focus:inset-ring focus:inset-ring-border"}
        data-testid="skip-link"
      >
        {labels.skip}
      </LinkPlain>
      <Container
        className={cn(
          "mx-auto w-full max-w-6xl px-4",
          "flex flex-wrap gap-4 py-4",
          (((layout as string) === "stacked") ? "flex-col items-center" : "items-center justify-between")
        )}
        data-slot="container"
      >
        <MenuEntry href={routes?.home} className="text-lg font-medium" testid="brand">
          {labels.brand}
        </MenuEntry>
        <NavBlock
          label={(landmarkLabel ? uniqLabel(tpl("{0}, {1}", labels.nav, landmarkLabel)) : labels.nav)}
          testid="site-nav"
        >
          <Group gap="4" align="center">
            <MenuEntry
              href={routes?.home}
              className="font-semibold"
              current={((current as string) === "home")}
              testid="nav-link"
            >
              {labels.home}
            </MenuEntry>
            <MenuEntry
              href={routes?.pricing}
              className="font-semibold"
              current={((current as string) === "pricing")}
              testid="nav-link"
            >
              {labels.pricing}
            </MenuEntry>
          </Group>
        </NavBlock>
        <Group gap="4" align="center">
          <Button variant="outline" size="sm" data-testid="theme-toggle" onClick={() => onTheme?.()}>
            {labels.theme}
          </Button>
          {(((actions as string) === "cta") && cta) ? (
            <Button variant="default" size="sm" href={urlOf(ctaHref)} data-testid="header-cta">
              {cta}
            </Button>
          ) : null}
        </Group>
      </Container>
    </Block>
  );
}

